const p = msg.payload || {};
const keys = ["temperature", "humidity", "pressure"];
let samples = context.get("samples") || { temperature: [], humidity: [], pressure: [] };
for (const key of keys) {
    const value = Number(p[key]);
    if (Number.isFinite(value)) {
        samples[key].push(value);
        if (samples[key].length > 100) samples[key].shift();
    }
}
context.set("samples", samples);
function stats(values) {
    if (!values.length) return { min: null, max: null, average: null };
    const min = Math.min(...values);
    const max = Math.max(...values);
    const average = values.reduce((a, b) => a + b, 0) / values.length;
    return { min: Number(min.toFixed(2)), max: Number(max.toFixed(2)), average: Number(average.toFixed(2)) };
}
const result = {
    temperature: stats(samples.temperature),
    humidity: stats(samples.humidity),
    pressure: stats(samples.pressure)
};
const rows = [
    ["Temperature (C)", result.temperature],
    ["Humidity (%RH)", result.humidity],
    ["Pressure (hPa)", result.pressure]
];
let html = "<!doctype html><html><head><meta charset='utf-8'><title>BME280 Statistics</title></head><body><h2>BME280 Statistics (last 100 samples)</h2><table border='1' cellpadding='8'><tr><th>Parameter</th><th>Minimum</th><th>Maximum</th><th>Average</th></tr>";
for (const row of rows) {
    html += "<tr><td>" + row[0] + "</td><td>" + (row[1].min ?? "-") + "</td><td>" + (row[1].max ?? "-") + "</td><td>" + (row[1].average ?? "-") + "</td></tr>";
}
html += "</table></body></html>";
msg.statusCode = 200;
msg.headers = { "Content-Type": "text/html; charset=utf-8" };
msg.payload = html;
const debugMsg = { payload: result };
return [msg, debugMsg];
